-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE scores(name TEXT, score INTEGER);
-- INSERT INTO scores VALUES('kim',90),('lee',85);
-- INSERT INTO scores VALUES('park',90),('choi',80);
SELECT rn, rk, drk
FROM (
  SELECT name,
    ROW_NUMBER() OVER (ORDER BY score DESC, name) AS rn,
    RANK() OVER (ORDER BY score DESC) AS rk,
    DENSE_RANK() OVER (ORDER BY score DESC) AS drk
  FROM scores
)
WHERE name = 'choi';

